{"metadata":{"kernelspec":{"name":"python3","display_name":"Python 3","language":"python"},"language_info":{"name":"python","version":"3.11.13","mimetype":"text/x-python","codemirror_mode":{"name":"ipython","version":3},"pygments_lexer":"ipython3","nbconvert_exporter":"python","file_extension":".py"},"kaggle":{"accelerator":"nvidiaTeslaT4","dataSources":[],"dockerImageVersionId":31193,"isInternetEnabled":true,"language":"python","sourceType":"script","isGpuEnabled":true}},"nbformat_minor":4,"nbformat":4,"cells":[{"cell_type":"code","source":"# %% [code] {\"execution\":{\"iopub.status.busy\":\"2025-11-30T01:45:49.052436Z\",\"iopub.execute_input\":\"2025-11-30T01:45:49.053083Z\",\"iopub.status.idle\":\"2025-11-30T01:45:49.056588Z\",\"shell.execute_reply.started\":\"2025-11-30T01:45:49.053056Z\",\"shell.execute_reply\":\"2025-11-30T01:45:49.055750Z\"}}\nimport warnings\nwarnings.filterwarnings(\"ignore\")\n\n# %% [markdown]\n# ### Data Preprocessing:\n# \n# The text dataset is processed and transformed, to use it for model training.\n# Steps:\n# - Loading Dataset\n# - Initialising a tokenizer object for the pretrained model of BERT Transformer\n# - The transformations on dataset involve\n#   - Encoding the words with their respective word 'id' from the BERT Model\n#   - The sentences are padded to make all the sentences of same length in our case the max_length = 200\n#   - Respective attention vectors are created for each sentence with value '1' for word and value '0' for padded words.\n# - This transformed requires to have a type of tensorflow tensor data. So we will transform the data into Tensorflow tensor data format.\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2025-11-30T01:45:50.180138Z\",\"iopub.execute_input\":\"2025-11-30T01:45:50.180426Z\",\"iopub.status.idle\":\"2025-11-30T01:45:54.321003Z\",\"shell.execute_reply.started\":\"2025-11-30T01:45:50.180404Z\",\"shell.execute_reply\":\"2025-11-30T01:45:54.320215Z\"}}\nfrom datasets import load_dataset \n\ndataset = load_dataset(\"ag_news\")\nsplit = dataset['train'].train_test_split(test_size=0.1, seed=42)\ntrain_ds = split[\"train\"]\nval_ds = split['test']\ntest_ds = dataset['test']\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2025-11-30T01:45:54.322268Z\",\"iopub.execute_input\":\"2025-11-30T01:45:54.322991Z\",\"iopub.status.idle\":\"2025-11-30T01:45:54.530076Z\",\"shell.execute_reply.started\":\"2025-11-30T01:45:54.322962Z\",\"shell.execute_reply\":\"2025-11-30T01:45:54.529212Z\"}}\nfrom transformers import AutoTokenizer\n\nmodel_name = \"bert-base-uncased\"\ntokenizer = AutoTokenizer.from_pretrained(model_name)\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2025-11-30T01:45:54.531197Z\",\"iopub.execute_input\":\"2025-11-30T01:45:54.531424Z\",\"iopub.status.idle\":\"2025-11-30T01:46:24.311609Z\",\"shell.execute_reply.started\":\"2025-11-30T01:45:54.531407Z\",\"shell.execute_reply\":\"2025-11-30T01:46:24.310863Z\"}}\ndef encode_batch(batch):\n    return tokenizer(\n        batch['text'],\n        max_length = 200,\n        truncation = True,\n        padding = \"max_length\"\n    )\n\ntrain_enc = train_ds.map(encode_batch, batched=True)\ntest_enc = test_ds.map(encode_batch, batched=True)\nval_enc = val_ds.map(encode_batch, batched=True)\n\n\ntrain_enc = train_enc.rename_column(\"label\", \"labels\")\ntest_enc = test_enc.rename_column(\"label\", \"labels\")\nval_enc = val_enc.rename_column(\"label\", \"labels\")\n\n\ntrain_enc.set_format(type = 'tensorflow', columns = ['input_ids','attention_mask', 'labels'])\ntest_enc.set_format(type = 'tensorflow', columns = ['input_ids','attention_mask', 'labels'])\nval_enc.set_format(type = 'tensorflow', columns = ['input_ids','attention_mask', 'labels'])\n\n\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2025-11-30T01:46:24.313061Z\",\"iopub.execute_input\":\"2025-11-30T01:46:24.313267Z\",\"iopub.status.idle\":\"2025-11-30T01:46:24.643079Z\",\"shell.execute_reply.started\":\"2025-11-30T01:46:24.313251Z\",\"shell.execute_reply\":\"2025-11-30T01:46:24.642284Z\"}}\nimport tensorflow as tf\n\ntf_train = train_enc.to_tf_dataset(\n    columns=[\"input_ids\", \"attention_mask\"],\n    label_cols=[\"labels\"],\n    shuffle=True,\n    batch_size=16,\n)\n\n\ntf_val = val_enc.to_tf_dataset(\n    columns=[\"input_ids\",\"attention_mask\"],\n    label_cols=[\"labels\"],\n    shuffle=False,\n    batch_size=16,\n)\n\ntf_test = test_enc.to_tf_dataset(\n    columns=[\"input_ids\", \"attention_mask\"],\n    label_cols=[\"labels\"],\n    shuffle=False,\n    batch_size=16,\n)\n\n\n\n# %% [markdown]\n# ### Model Initialization\n# \n# For the text classification task, we employ the BERT Base Uncased model, which is a pretrained Transformer-based encoder.\n# BERT is a bidirectional autoencoder architecture trained on large-scale corpora using two objectives:\n# \n# - Masked Language Modeling (MLM) — learns deep contextual word representations\n# - Next Sentence Prediction (NSP) — learns relationships between sentences\n# \n# Because of this pretraining, BERT produces rich semantic embeddings for every token and for the entire sentence through the [CLS] embedding.\n# \n# #### How BERT is used in our classification task\n# \n# For sequence (text) classification, we follow the standard fine-tuning setup:\n# \n# - The input text is tokenized into word-piece tokens and converted to integer IDs.\n# \n# - These token IDs and their attention masks are passed into BERT’s encoder stack.\n# \n# - BERT produces a contextual embedding for every token and a special [CLS] embedding, which summarizes the meaning of the entire input sequence.\n# \n# On top of this [CLS] embedding, we place a fully connected classification layer:\n# \n# $$\n# \\mathbf{h}_{\\text{CLS}} \\in \\mathbb{R}^{768} \\;\\longrightarrow\\; \\text{Dense}(4)\n# $$\n# \n# \n# where 4 corresponds to the four AG News categories.\n# \n# This classification layer is randomly initialized, and only its weights are trained from scratch, while BERT’s encoder weights are fine-tuned during training to adapt the representations to our dataset.\n# \n# #### What the model learns\n# \n# - BERT provides context-aware embeddings that capture syntax, semantics, and long-range dependencies.\n# \n# - The classification head learns to map these embeddings to a 4-class probability distribution using a softmax activation.\n# \n# - Training optimizes the cross-entropy loss between predicted and true labels.\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2025-11-30T01:46:24.643898Z\",\"iopub.execute_input\":\"2025-11-30T01:46:24.644131Z\",\"iopub.status.idle\":\"2025-11-30T01:46:26.690288Z\",\"shell.execute_reply.started\":\"2025-11-30T01:46:24.644114Z\",\"shell.execute_reply\":\"2025-11-30T01:46:26.689486Z\"}}\nfrom transformers import AutoTokenizer, TFBertModel\n\nmodel_name = \"bert-base-uncased\"\n\ntokenizer = AutoTokenizer.from_pretrained(model_name)\n\nbert = TFBertModel.from_pretrained(\n    model_name,\n    from_pt=True  # IMPORTANT: loads PyTorch weights into TF\n)\n\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2025-11-30T01:46:26.691846Z\",\"iopub.execute_input\":\"2025-11-30T01:46:26.692162Z\",\"iopub.status.idle\":\"2025-11-30T01:46:26.698257Z\",\"shell.execute_reply.started\":\"2025-11-30T01:46:26.692138Z\",\"shell.execute_reply\":\"2025-11-30T01:46:26.697414Z\"}}\nimport tensorflow as tf\nfrom tensorflow.keras.layers import Input, Dense, Dropout\nfrom tensorflow.keras.models import Model\n\nmax_len = 200\n\ninput_ids = Input(shape=(max_len,), dtype=tf.int32, name=\"input_ids\")\nattention_mask = Input(shape=(max_len,), dtype=tf.int32, name=\"attention_mask\")\n\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2025-11-30T01:46:26.699130Z\",\"iopub.execute_input\":\"2025-11-30T01:46:26.699338Z\",\"iopub.status.idle\":\"2025-11-30T01:46:26.947428Z\",\"shell.execute_reply.started\":\"2025-11-30T01:46:26.699323Z\",\"shell.execute_reply\":\"2025-11-30T01:46:26.946763Z\"}}\n# Add output shape\n\nbert_output = tf.keras.layers.Lambda(\n    lambda x: bert(x[\"input_ids\"], attention_mask=x[\"attention_mask\"])[0],\n    output_shape=(max_len, 768)\n)({\"input_ids\": input_ids, \"attention_mask\": attention_mask})\n\ncls_embedding = bert_output[:, 0, :]  # shape = (batch, 768)\n\n\nx = tf.keras.layers.Dropout(0.2)(cls_embedding)\nx = tf.keras.layers.Dense(128, activation=\"relu\")(x)\noutput = tf.keras.layers.Dense(4, activation=\"softmax\")(x)\n\nmodel = tf.keras.Model(inputs=[input_ids, attention_mask], outputs=output)\nmodel.compile(\n    optimizer=tf.keras.optimizers.Adam(1e-5),\n    loss=\"sparse_categorical_crossentropy\",\n    metrics=[\"accuracy\"]\n)\n\nmodel.summary()\n\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2025-11-30T01:48:31.278996Z\",\"iopub.execute_input\":\"2025-11-30T01:48:31.279690Z\",\"iopub.status.idle\":\"2025-11-30T01:48:34.204398Z\",\"shell.execute_reply.started\":\"2025-11-30T01:48:31.279666Z\",\"shell.execute_reply\":\"2025-11-30T01:48:34.203771Z\"}}\n%%time \nimport time\ncpu_start_time = time.process_time()\nhistory = model.fit(\n    tf_train,\n    validation_data = tf_val,\n    epochs = 10,\n    batch_size = 1000\n)\ncpu_end_time = time.process_time()\ncpu_train_time = cpu_end_time - cpu_start_time\nprint(cpu_train_time)\n\n# %% [markdown]\n# #### Model Evaluation:\n# \n# We will check the model on training and test dataset and collect various model metrics, They are:\n# - Train Dataset Metrics\n# - Test Dataset Metrics\n# - Metrics used:\n#   - Accuracy\n#   - F1 Score\n# - Inference Time of Test Dataset\n# - FLOP's for each Sample Inference\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2025-11-30T01:45:28.417413Z\",\"iopub.execute_input\":\"2025-11-30T01:45:28.417624Z\",\"iopub.status.idle\":\"2025-11-30T01:45:28.425160Z\",\"shell.execute_reply.started\":\"2025-11-30T01:45:28.417608Z\",\"shell.execute_reply\":\"2025-11-30T01:45:28.423904Z\"}}\nimport time\nimport numpy as np\n\n%%time\n# Start CPU timer\ncpu_start_time = time.process_time()\nstart_wall = time.time()\n\n# Run prediction\ny_pred_probs = model.predict(\n    {\n        \"input_ids\": test_enc[\"input_ids\"],\n        \"attention_mask\": test_enc[\"attention_mask\"]\n    },\n    batch_size=32   # adjust based on your GPU\n)\n\ny_test_pred = np.argmax(y_test_probs, axis=1\n\n# Stop timers\ncpu_end_time = time.process_time()\nend_wall = time.time()\n\ncpu_time_inf = cpu_end_time - cpu_start_time\nwall_time_inf = end_wall - start_wall\n\nprint(\"CPU inference time:\", cpu_time_inf, \"seconds\")\nprint(\"Wall-clock inference time:\", wall_time_inf, \"seconds\")\n\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2025-11-30T01:45:28.425693Z\",\"iopub.status.idle\":\"2025-11-30T01:45:28.426001Z\",\"shell.execute_reply.started\":\"2025-11-30T01:45:28.425843Z\",\"shell.execute_reply\":\"2025-11-30T01:45:28.425858Z\"}}\ny_train_probs = model.predict(\n    {\n        \"input_ids\": train_enc[\"input_ids\"],\n        \"attention_mask\": train_enc[\"attention_mask\"]\n    },\n    batch_size=32\n)\n\ny_train_pred = np.argmax(y_train_probs, axis=1)\n\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2025-11-30T01:45:28.427675Z\",\"iopub.status.idle\":\"2025-11-30T01:45:28.427923Z\",\"shell.execute_reply.started\":\"2025-11-30T01:45:28.427803Z\",\"shell.execute_reply\":\"2025-11-30T01:45:28.427816Z\"}}\nprint(\"Training Accuracy\")\ntrain_accuracy = accuracy_score(y_train, y_train_pred)\ntrain_f1 = f1_score(y_train, y_train_pred, average='weighted', zero_division=0)\ntrain_report = classification_report(y_train, y_train_pred)\nprint('\\n Training Accuracy',train_accuracy)\nprint('\\n Training F1 Score',train_f1)\nprint('\\n Training Classification Report',train_report)\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2025-11-30T01:45:28.428979Z\",\"iopub.status.idle\":\"2025-11-30T01:45:28.429318Z\",\"shell.execute_reply.started\":\"2025-11-30T01:45:28.429198Z\",\"shell.execute_reply\":\"2025-11-30T01:45:28.429212Z\"}}\nprint(\"Test Accuracy\")\ntest_accuracy = accuracy_score(y_test, y_pred_test)\ntest_f1 = f1_score(y_test, y_pred_test, average='weighted', zero_division=0)\ntest_report = classification_report(y_test,y_pred_test)\nprint('\\n Test Accuracy',test_accuracy)\nprint('\\n Test F1 Score',test_f1)\nprint('\\n Test Classification Report',test_report)\n\n# %% [markdown]\n# ##### FLOP's Calculation: \n# A Single BERT Layer includes:\n# \n# - Q, K, V projections → 3 matrix multiplications\n# \n# - Attention softmax\n# \n# - Attention × V\n# \n# - Feed-forward network (two dense layers)\n# \n# - Layer norm, dropout, residuals\n# \n# A 12-layer BERT-base model ≈ 22Billion FLOPs per sequence of length 200.\n# \n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2025-11-30T01:45:28.430328Z\",\"iopub.status.idle\":\"2025-11-30T01:45:28.430601Z\",\"shell.execute_reply.started\":\"2025-11-30T01:45:28.430465Z\",\"shell.execute_reply\":\"2025-11-30T01:45:28.430481Z\"}}\nflops = 22_000_000_000\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2025-11-30T01:45:28.431778Z\",\"iopub.status.idle\":\"2025-11-30T01:45:28.432126Z\",\"shell.execute_reply.started\":\"2025-11-30T01:45:28.431962Z\",\"shell.execute_reply\":\"2025-11-30T01:45:28.431977Z\"}}\nresults = {}\nresults[('BERT Transformer','MLP Model')] = {\n                                    'Train':\n                                            {'accuracy': train_accuracy,\n                                            'f1_score': train_f1,\n                                            'report': train_report,\n                                            'training_time': cpu_train_time},\n                                    'Test':\n                                            {'accuracy': test_accuracy,\n                                            'f1_score': test_f1,\n                                            'report': test_report,\n                                            'inference_time':cpu_time_inf,\n                                            \"flops/sample\": flops}}\n\n# %% [code]\n\n\n# %% [code]\n\n\n# %% [markdown]\n# ## Tabulate:\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2025-11-30T01:45:28.434695Z\",\"iopub.status.idle\":\"2025-11-30T01:45:28.435061Z\",\"shell.execute_reply.started\":\"2025-11-30T01:45:28.434903Z\",\"shell.execute_reply\":\"2025-11-30T01:45:28.434919Z\"}}\n# create DataFrame\nimport pandas as pd\n\n# flatten nested dict into a list of rows\nrows = []\n\nfor (vectorizer, model), metrics in results.items():\n    row = {\n        \"Vectorizer\": vectorizer,\n        \"Model\": model,\n        \"Train_Accuracy\": metrics[\"Train\"][\"accuracy\"],\n        \"Train_F1\": metrics[\"Train\"][\"f1_score\"],\n        \"Test_Accuracy\": metrics[\"Test\"][\"accuracy\"],\n        \"Test_F1\": metrics[\"Test\"][\"f1_score\"],\n        \"Inference_Time\": metrics[\"Test\"].get(\"inference_time\", None),\n        \"FLOPs_per_Sample\": metrics[\"Test\"].get(\"flops/sample\", None),\n        \"Training_Time\": metrics['Train'].get('training_time',None)\n    }\n    rows.append(row)\n\n# create DataFrame\ndf_results = pd.DataFrame(rows)\n\n# optional: set a clean display order\ndf_results = df_results[\n    [\"Vectorizer\", \"Model\", \"Train_Accuracy\", \"Train_F1\",\n     \"Test_Accuracy\", \"Test_F1\", \"Inference_Time\", \"FLOPs_per_Sample\",\"Training_Time\"]\n]\n\nprint(df_results)\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2025-11-30T01:45:28.436067Z\",\"iopub.status.idle\":\"2025-11-30T01:45:28.436810Z\",\"shell.execute_reply.started\":\"2025-11-30T01:45:28.436686Z\",\"shell.execute_reply\":\"2025-11-30T01:45:28.436702Z\"}}\ndf_results.to_csv('datasets/w2vec_emb.csv')\n\n# %% [code]\n\n\n# %% [code]\n","metadata":{"_uuid":"7a0caa0f-7d30-4471-a333-226cb1e34c7d","_cell_guid":"d7e0fc58-574e-4eed-9f47-5268502d6aa0","trusted":true,"collapsed":false,"jupyter":{"outputs_hidden":false}},"outputs":[],"execution_count":null}]}